        state.update_harmony_range(Note::E4); // 64
                                              // Range is 4 semitones (major 3rd) - narrow
        assert!(state.is_harmony_range_narrow());

        state.update_harmony_range(Note::C5); // 72
                                              // Range is now 12 semitones - not narrow
        assert!(!state.is_harmony_range_narrow());
    }

